void reverse(int a[], int n)
{
    int left_index = 0;
    int right_index = n - 1;
    while (left_index < right_index)
    {
        // dono taraf se swap karo
        a[left_index] = a[right_index];
        a[right_index] = a[left_index];
        left_index = left_index + 1;
        right_index = right_index - 1;
    }
}
